-- =====================================================================
-- GastroMatch - Schema PostgreSQL (v2.0.0)
-- Convertido do schema MySQL v1.0.0 (guardado em legado-mysql/).
-- Alvo: PostgreSQL 15 ou superior (Supabase e o container do docker-compose).
--
-- O QUE MUDOU EM RELAÇÃO AO MYSQL
--   AUTO_INCREMENT ........ GENERATED BY DEFAULT AS IDENTITY
--   ENUM(...) ............. VARCHAR + CHECK (os valores são os mesmos dos enums Java;
--                           um valor novo exige alterar o CHECK)
--   DATETIME .............. TIMESTAMPTZ (o Java usa Instant, sempre em UTC)
--   TINYINT(1) ............ BOOLEAN        FLOAT ... REAL
--   ON UPDATE CURRENT_TIMESTAMP -> gatilho (trigger) set_atualizado_em()
--   UNIQUE sem diferenciar maiúscula (collation _ci do MySQL) -> índice único em lower(coluna)
--   Crases ................ removidas (nomes já são minúsculos)
--
-- COMO RODAR
--   Docker (docker-compose.yml): roda sozinho na primeira criação do banco.
--   Supabase: colar no SQL Editor (ou ver Backend/SETUP-BANCO.md). Pode ser
--   executado mais de uma vez: usa IF NOT EXISTS e não apaga nada.
--
-- LEGENDA DOS COMENTÁRIOS (herdada da v1)
--   [DOC] fiel à documentação   [PROPOSTA] a confirmar   [AJUSTE] divergência técnica
--   [ADIÇÃO] coluna/constraint que a documentação não lista
-- =====================================================================

-- Busca de receitas e ingredientes sem diferenciar acento ("acucar" acha "Açúcar").
-- No Supabase a extensão vai para o schema public (o padrão ao rodar no SQL Editor).
CREATE EXTENSION IF NOT EXISTS unaccent;

-- Gatilho comum: mantém atualizado_em em dia a cada UPDATE (no MySQL era ON UPDATE).
-- search_path vazio é a forma recomendada pelo Supabase para funções.
CREATE OR REPLACE FUNCTION set_atualizado_em() RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  NEW.atualizado_em = now();
  RETURN NEW;
END;
$$;

-- ---------------------------------------------------------------------
-- 1. profissional (tabela mãe: chef, nutricionista, restaurante)
-- ---------------------------------------------------------------------
-- `role` é o DISCRIMINADOR do tipo de perfil. Não tem relação com permissões
-- de acesso (o sistema não terá autorização por papéis).
-- Débito assumido pelo time [DOC]: o banco NÃO garante que `role` bate com a
-- tabela filha existente. Essa validação é do backend, no cadastro.
CREATE TABLE IF NOT EXISTS profissional (
  id                    INT          GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  bio                   VARCHAR(500) NULL,
  role                  VARCHAR(20)  NOT NULL,
  comprovante_profissao VARCHAR(500) NULL,
  criado_em             TIMESTAMPTZ  NOT NULL DEFAULT now(),
  atualizado_em         TIMESTAMPTZ  NOT NULL DEFAULT now(),
  CONSTRAINT chk_profissional_role CHECK (role IN ('CHEF','NUTRICIONISTA','RESTAURANTE'))
);

-- ---------------------------------------------------------------------
-- 2. usuario
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS usuario (
  id                  INT          GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email               VARCHAR(255) NOT NULL,
  password            VARCHAR(100) NOT NULL,                      -- hash BCrypt (60 caracteres)
  username            VARCHAR(50)  NOT NULL,
  capa                VARCHAR(500) NULL,
  id_profissional     INT          NULL,
  -- [ADIÇÃO] momento da última troca de senha: tokens emitidos ANTES dele são recusados.
  senha_alterada_em   TIMESTAMPTZ  NULL,
  -- [ADIÇÃO] NULL = email ainda não verificado (verificação planejada).
  email_verificado_em TIMESTAMPTZ  NULL,
  criado_em           TIMESTAMPTZ  NOT NULL DEFAULT now(),
  atualizado_em       TIMESTAMPTZ  NOT NULL DEFAULT now(),
  -- [ADIÇÃO] UNIQUE garante a relação 0..1: um profissional tem no máximo um usuário
  CONSTRAINT uq_usuario_profissional UNIQUE (id_profissional),
  CONSTRAINT fk_usuario_profissional
    FOREIGN KEY (id_profissional) REFERENCES profissional (id)
    ON DELETE SET NULL                                            -- [PROPOSTA] a conta sobrevive ao perfil
);
-- Email e username únicos SEM diferenciar maiúscula (no MySQL a collation já fazia isso).
CREATE UNIQUE INDEX IF NOT EXISTS uq_usuario_email    ON usuario (lower(email));
CREATE UNIQUE INDEX IF NOT EXISTS uq_usuario_username ON usuario (lower(username));

-- ---------------------------------------------------------------------
-- 2.1 refresh_token (sessões de login)
-- ---------------------------------------------------------------------
-- [ADIÇÃO] Não existe no DER: é infraestrutura do login (RefreshToken.java).
-- Guarda só o HASH SHA-256 do token (64 caracteres em hexadecimal); o valor
-- puro fica apenas com o cliente. Se o banco vazar, os tokens não servem.
-- `revogado` marca o token já usado (rotação) ou encerrado (logout).
CREATE TABLE IF NOT EXISTS refresh_token (
  id         INT         GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  token_hash VARCHAR(64) NOT NULL,
  id_usuario INT         NOT NULL,
  expira_em  TIMESTAMPTZ NOT NULL,
  revogado   BOOLEAN     NOT NULL DEFAULT FALSE,
  CONSTRAINT uq_refresh_token_token_hash UNIQUE (token_hash),
  CONSTRAINT fk_refresh_token_usuario
    FOREIGN KEY (id_usuario) REFERENCES usuario (id)
    ON DELETE CASCADE                                             -- excluir a conta apaga as sessões
);

-- ---------------------------------------------------------------------
-- 3. restaurante
-- ---------------------------------------------------------------------
-- [AJUSTE] A documentação define a relação restaurante (1,1) - (1,1) profissional,
-- mas não lista a coluna que a implementa. Adicionada `id_profissional`.
-- A regra "todo restaurante exige ao menos 1 chef" é do backend.
CREATE TABLE IF NOT EXISTS restaurante (
  id              INT          GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  cnpj            VARCHAR(18)  NOT NULL,                          -- [PROPOSTA] cabe com máscara
  nome            VARCHAR(150) NOT NULL,
  bio             VARCHAR(500) NULL,
  numero          INT          NULL,
  rua             VARCHAR(150) NULL,
  cep             VARCHAR(9)   NULL,
  bairro          VARCHAR(100) NULL,
  cidade          VARCHAR(100) NULL,
  estado          VARCHAR(50)  NULL,
  -- [ADIÇÃO] posição no mapa (graus decimais). As duas juntas ou nenhuma.
  -- Bancos que já existiam recebem estas colunas por GastroDB_v2.1.0_restaurante_localizacao.sql.
  latitude        DOUBLE PRECISION NULL,
  longitude       DOUBLE PRECISION NULL,
  id_profissional INT          NOT NULL,
  criado_em       TIMESTAMPTZ  NOT NULL DEFAULT now(),
  atualizado_em   TIMESTAMPTZ  NOT NULL DEFAULT now(),
  CONSTRAINT chk_restaurante_latitude  CHECK (latitude  BETWEEN -90  AND 90),
  CONSTRAINT chk_restaurante_longitude CHECK (longitude BETWEEN -180 AND 180),
  CONSTRAINT chk_restaurante_posicao   CHECK ((latitude IS NULL) = (longitude IS NULL)),
  CONSTRAINT uq_restaurante_cnpj         UNIQUE (cnpj),
  CONSTRAINT uq_restaurante_profissional UNIQUE (id_profissional),
  CONSTRAINT fk_restaurante_profissional
    FOREIGN KEY (id_profissional) REFERENCES profissional (id)
    ON DELETE RESTRICT
);

-- ---------------------------------------------------------------------
-- 4. chef
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS chef (
  id              INT         GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_profissional INT         NOT NULL,
  -- [PROPOSTA] valores de exemplo; a documentação só diz "área de especialidade"
  especializacao  VARCHAR(30) NULL,
  id_restaurante  INT         NULL,
  criado_em       TIMESTAMPTZ NOT NULL DEFAULT now(),
  atualizado_em   TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT chk_chef_especializacao CHECK (especializacao IN
    ('CONFEITARIA','PANIFICACAO','CARNES','MASSAS','COZINHA_VEGETARIANA')),
  -- [ADIÇÃO] no máximo um chef por profissional
  CONSTRAINT uq_chef_profissional UNIQUE (id_profissional),
  CONSTRAINT fk_chef_profissional
    FOREIGN KEY (id_profissional) REFERENCES profissional (id)
    ON DELETE RESTRICT,
  CONSTRAINT fk_chef_restaurante
    FOREIGN KEY (id_restaurante) REFERENCES restaurante (id)
    ON DELETE SET NULL                                            -- [PROPOSTA]
);

-- ---------------------------------------------------------------------
-- 5. nutricionista
-- ---------------------------------------------------------------------
-- Não há aprovação: quem se cadastra já nasce APROVADO. O status só serve para a
-- equipe esconder alguém do diretório (REJEITADO), direto no banco.
-- `status_verificacao` NUNCA deve ser aceito de entrada da API.
CREATE TABLE IF NOT EXISTS nutricionista (
  id                 INT         GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  crn                VARCHAR(20) NOT NULL,                        -- [PROPOSTA] tamanho
  id_profissional    INT         NOT NULL,
  status_verificacao VARCHAR(10) NOT NULL DEFAULT 'APROVADO',
  -- [ADIÇÃO] quando a equipe revisou o perfil (NULL se nunca revisou)
  verificado_em      TIMESTAMPTZ NULL,
  criado_em          TIMESTAMPTZ NOT NULL DEFAULT now(),
  atualizado_em      TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT chk_nutricionista_status CHECK (status_verificacao IN ('PENDENTE','APROVADO','REJEITADO')),
  CONSTRAINT uq_nutricionista_crn          UNIQUE (crn),
  CONSTRAINT uq_nutricionista_profissional UNIQUE (id_profissional),
  CONSTRAINT fk_nutricionista_profissional
    FOREIGN KEY (id_profissional) REFERENCES profissional (id)
    ON DELETE RESTRICT
);

-- ---------------------------------------------------------------------
-- 6. receita
-- ---------------------------------------------------------------------
-- Os valores dos CHECKs abaixo são [PROPOSTA]: a documentação cita só exemplos.
CREATE TABLE IF NOT EXISTS receita (
  id             INT           GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nome           VARCHAR(150)  NOT NULL,
  descricao      VARCHAR(1000) NULL,
  imagem         VARCHAR(500)  NULL,
  -- [ADIÇÃO] link do YouTube; o backend só aceita URL de youtube.com / youtu.be.
  -- O front monta o iframe com /embed/<id>?start=<etapa_receita.timestamp_video>.
  video_url      VARCHAR(500)  NULL,
  n_porcoes      INT           NOT NULL,
  dificuldade    VARCHAR(10)   NOT NULL,
  tipo           VARCHAR(20)   NOT NULL,
  metodo_preparo VARCHAR(20)   NULL,
  ocasiao        VARCHAR(20)   NULL,
  tempo_preparo  INT           NOT NULL,                          -- em minutos
  perfil         VARCHAR(20)   NULL,
  id_chef        INT           NOT NULL,
  criado_em      TIMESTAMPTZ   NOT NULL DEFAULT now(),
  atualizado_em  TIMESTAMPTZ   NOT NULL DEFAULT now(),
  -- [ADIÇÃO] evita divisão por zero no ajuste automático de porções
  CONSTRAINT chk_receita_n_porcoes CHECK (n_porcoes > 0),
  CONSTRAINT chk_receita_dificuldade CHECK (dificuldade IN ('FACIL','MEDIO','DIFICIL')),
  CONSTRAINT chk_receita_tipo CHECK (tipo IN
    ('CAFE_DA_MANHA','ALMOCO','JANTAR','LANCHE','SOBREMESA')),
  CONSTRAINT chk_receita_metodo_preparo CHECK (metodo_preparo IN
    ('FORNO','AIR_FRYER','GRELHA','FOGAO')),
  CONSTRAINT chk_receita_ocasiao CHECK (ocasiao IN
    ('ANIVERSARIO','CHURRASCO','NATAL','DIA_A_DIA')),
  CONSTRAINT chk_receita_perfil CHECK (perfil IN
    ('VEGANO','VEGETARIANO','LOW_CARB','SEM_GLUTEN','SEM_LACTOSE')),
  CONSTRAINT fk_receita_chef
    FOREIGN KEY (id_chef) REFERENCES chef (id)
    ON DELETE RESTRICT
);

-- ---------------------------------------------------------------------
-- 7. etapa_receita
-- ---------------------------------------------------------------------
-- [AJUSTE] PK simples em `id` (a `dica` referencia só `etapa_receita.id`),
-- `id_receita` como FK comum e índice (id_receita, ordem) para listar na ordem.
CREATE TABLE IF NOT EXISTS etapa_receita (
  id              INT           GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_receita      INT           NOT NULL,
  ordem           INT           NOT NULL,
  titulo          VARCHAR(150)  NOT NULL,
  instrucao       VARCHAR(2000) NOT NULL,                         -- [PROPOSTA] tamanho
  timestamp_video INT           NULL,                             -- segundo do vídeo
  imagem          VARCHAR(500)  NULL,
  criado_em       TIMESTAMPTZ   NOT NULL DEFAULT now(),
  atualizado_em   TIMESTAMPTZ   NOT NULL DEFAULT now(),
  CONSTRAINT fk_etapa_receita_receita
    FOREIGN KEY (id_receita) REFERENCES receita (id)
    ON DELETE CASCADE                                             -- [PROPOSTA] etapa não existe sem a receita
);
CREATE INDEX IF NOT EXISTS idx_etapa_receita_ordem ON etapa_receita (id_receita, ordem);

-- ---------------------------------------------------------------------
-- 8. dica (dica de chef ou erro comum, vinculada a uma etapa)
-- ---------------------------------------------------------------------
-- [DOC] A FK do autor fica em `dica` (id_chef): um chef publica várias dicas.
CREATE TABLE IF NOT EXISTS dica (
  id               INT           GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  conteudo         VARCHAR(1000) NOT NULL,
  tipo             VARCHAR(12)   NOT NULL,
  id_etapa_receita INT           NOT NULL,
  id_chef          INT           NOT NULL,
  criado_em        TIMESTAMPTZ   NOT NULL DEFAULT now(),
  atualizado_em    TIMESTAMPTZ   NOT NULL DEFAULT now(),
  CONSTRAINT chk_dica_tipo CHECK (tipo IN ('DICA','ERRO_COMUM')),
  CONSTRAINT fk_dica_etapa_receita
    FOREIGN KEY (id_etapa_receita) REFERENCES etapa_receita (id)
    ON DELETE CASCADE,
  CONSTRAINT fk_dica_chef
    FOREIGN KEY (id_chef) REFERENCES chef (id)
    ON DELETE RESTRICT
);

-- ---------------------------------------------------------------------
-- 9. ingrediente (catálogo com dados nutricionais por porcao_base)
-- ---------------------------------------------------------------------
-- Cálculo no backend: (quantidade / porcao_base) x valor nutricional.
-- REAL mantido (era FLOAT no MySQL), igual ao `float` da entidade Java.
CREATE TABLE IF NOT EXISTS ingrediente (
  id            INT          GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nome          VARCHAR(100) NOT NULL,
  porcao_base   REAL         NOT NULL,
  calorias      REAL         NOT NULL,
  gordura       REAL         NOT NULL,
  proteina      REAL         NOT NULL,
  carboidrato   REAL         NOT NULL,
  criado_em     TIMESTAMPTZ  NOT NULL DEFAULT now(),
  atualizado_em TIMESTAMPTZ  NOT NULL DEFAULT now(),
  -- [ADIÇÃO] porcao_base é divisor na fórmula; zero quebraria o cálculo
  CONSTRAINT chk_ingrediente_porcao_base CHECK (porcao_base > 0)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_ingrediente_nome ON ingrediente (lower(nome));

-- ---------------------------------------------------------------------
-- 10. ingrediente_receita (associativa receita x ingrediente)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ingrediente_receita (
  id             INT         GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  quantidade     REAL        NOT NULL,
  unidade_medida VARCHAR(10) NOT NULL,
  id_receita     INT         NOT NULL,
  id_ingrediente INT         NOT NULL,
  criado_em      TIMESTAMPTZ NOT NULL DEFAULT now(),
  atualizado_em  TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT chk_ingrediente_receita_quantidade CHECK (quantidade > 0),  -- [ADIÇÃO]
  CONSTRAINT chk_ingrediente_receita_unidade CHECK (unidade_medida IN ('G','ML','UNIDADE','XICARA')),
  CONSTRAINT fk_ingrediente_receita_receita
    FOREIGN KEY (id_receita) REFERENCES receita (id)
    ON DELETE CASCADE,
  CONSTRAINT fk_ingrediente_receita_ingrediente
    FOREIGN KEY (id_ingrediente) REFERENCES ingrediente (id)
    ON DELETE RESTRICT
);

-- ---------------------------------------------------------------------
-- 11. comentario (comentário e nota na mesma linha)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS comentario (
  id            INT           GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_receita    INT           NOT NULL,
  id_usuario    INT           NOT NULL,
  texto         VARCHAR(2000) NOT NULL,
  nota          REAL          NULL,
  foto          VARCHAR(500)  NULL,
  criado_em     TIMESTAMPTZ   NOT NULL DEFAULT now(),
  atualizado_em TIMESTAMPTZ   NOT NULL DEFAULT now(),
  CONSTRAINT fk_comentario_receita
    FOREIGN KEY (id_receita) REFERENCES receita (id)
    ON DELETE CASCADE,
  CONSTRAINT fk_comentario_usuario
    FOREIGN KEY (id_usuario) REFERENCES usuario (id)
    ON DELETE CASCADE                                             -- [PROPOSTA] apagar conta apaga comentários
);
CREATE INDEX IF NOT EXISTS idx_comentario_receita_data ON comentario (id_receita, criado_em);

-- ---------------------------------------------------------------------
-- 12. favorito (associativa usuario x receita)
-- ---------------------------------------------------------------------
-- Só `criado_em`: favoritar e desfavoritar são INSERT e DELETE.
CREATE TABLE IF NOT EXISTS favorito (
  id         INT         GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_usuario INT         NOT NULL,
  id_receita INT         NOT NULL,
  criado_em  TIMESTAMPTZ NOT NULL DEFAULT now(),
  -- [ADIÇÃO] favoritar duas vezes a mesma receita não faz sentido
  CONSTRAINT uq_favorito_usuario_receita UNIQUE (id_usuario, id_receita),
  CONSTRAINT fk_favorito_usuario
    FOREIGN KEY (id_usuario) REFERENCES usuario (id)
    ON DELETE CASCADE,
  CONSTRAINT fk_favorito_receita
    FOREIGN KEY (id_receita) REFERENCES receita (id)
    ON DELETE CASCADE
);

-- ---------------------------------------------------------------------
-- Gatilhos de atualizado_em (todas as tabelas que têm a coluna)
-- ---------------------------------------------------------------------
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['profissional','usuario','restaurante','chef','nutricionista',
                           'receita','etapa_receita','dica','ingrediente','ingrediente_receita','comentario']
  LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS trg_%s_atualizado_em ON %I', t, t);
    EXECUTE format('CREATE TRIGGER trg_%s_atualizado_em BEFORE UPDATE ON %I '
                   'FOR EACH ROW EXECUTE FUNCTION set_atualizado_em()', t, t);
  END LOOP;
END;
$$;

-- ---------------------------------------------------------------------
-- Segurança do Supabase (RLS)
-- ---------------------------------------------------------------------
-- O Supabase expõe as tabelas do schema public por uma API automática, acessível
-- com a chave pública (anon). Sem RLS, qualquer pessoa leria `usuario` (hashes de
-- senha) e `refresh_token`. Com RLS ligado e SEM políticas, essa API não enxerga
-- nada. A nossa API Spring conecta com o usuário dono das tabelas (postgres), que
-- ignora o RLS, então continua funcionando normalmente.
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['profissional','usuario','refresh_token','restaurante','chef','nutricionista',
                           'receita','etapa_receita','dica','ingrediente','ingrediente_receita',
                           'comentario','favorito']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
  END LOOP;
END;
$$;

-- =====================================================================
-- RESET DE DESENVOLVIMENTO (comentado de propósito)
-- APAGA TODAS AS TABELAS E DADOS. Usar apenas em banco local.
-- =====================================================================
-- DROP TABLE IF EXISTS favorito, comentario, ingrediente_receita, ingrediente, dica,
--   etapa_receita, receita, nutricionista, chef, restaurante, refresh_token,
--   usuario, profissional CASCADE;
